/* MPSC Practice Hub 2
 * ---------------------------------------------------------------------------
 * A browse + drill + mock-test shell over MPSC past papers.
 *
 * Hard design rule: NOTHING about a specific paper lives in this file. Every
 * exam name, paper, section heading, topic filter and mark scheme is read out
 * of window.PH2_PAPERS (generated by tools/practice-hub-build/build.py).
 * Adding a paper must never require touching app.js — if you find yourself
 * about to type a paperId in here, put it in the data instead.
 *
 * The other rule, inherited from CLAUDE.md: a derived answer must never be
 * able to read as authoritative. None of these papers has an official MPSC
 * answer key, so every answer here is `derived` and every question renders its
 * confidence. Where our answer differs from the highlighted "marked" answer in
 * the source PDF, the question says so out loud rather than quietly winning.
 */
(function () {
  'use strict';

  var PAPERS = (window.PH2_PAPERS || []).slice();
  var META = window.PH2_META || { topics: [], groups: [], totals: {} };
  var STORE_KEY = 'ph2:v1';   // deliberately its own namespace — see BUILD_GUIDE
                              // on the shared-localStorage bug that corrupted
                              // two apps' progress at once.
  var LETTERS = ['a', 'b', 'c', 'd'];

  /* ------------------------------------------------------------------ index */

  var ALL = [];                 // every question, flat, in paper order
  var BY_KEY = {};              // key -> question
  var PAPER_BY_ID = {};

  function indexPaper(p) {
    PAPER_BY_ID[p.paperId] = p;
    (p.questions || []).forEach(function (q) {
      q._paper = p;
      BY_KEY[q.key] = q;
      ALL.push(q);
    });
  }

  PAPERS.forEach(indexPaper);

  function slugify(value) {
    return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  }

  /* Current Affairs is maintained as dated JSON files by its own pipeline.
   * Adapt those records into the same paper/question contract as the static
   * past-paper bundle, without copying them into generated papers.js. */
  function currentAffairsPaper(day) {
    var date = day.date;
    var questions = (day.mcqs || []).map(function (q, i) {
      var topicSlug = 'ca-' + slugify(q.topic || 'general');
      return {
        id: q.id,
        n: i + 1,
        part: 'CA',
        direction: null,
        q: q.question,
        opts: q.options,
        answer: q.correctAnswer,
        marked: null,
        conf: 'medium',
        why: q.explanation,
        topic: topicSlug,
        topicLabel: q.topic || 'Current Affairs',
        flag: null,
        source: 'current-affairs',
        key: 'ca:' + date + ':' + q.id,
        topicGroup: 'gk',
        disagrees: false
      };
    });
    return {
      paperId: 'current-affairs-' + date,
      exam: 'MPSC Current Affairs',
      examShort: 'CA',
      dept: 'Daily current-affairs digest',
      sitting: 'Daily · ' + date,
      year: Number(date.slice(0, 4)),
      paper: date,
      paperTitle: day.source && day.source.title ? day.source.title : 'Current Affairs',
      sittingLabel: 'Current Affairs · ' + date,
      series: null,
      maxMarks: questions.length,
      durationMin: Math.max(15, Math.ceil(questions.length * 1.25)),
      negativeMark: 0,
      markPerQuestion: 1,
      sourcePdf: day.source && day.source.links ? day.source.links.join(' · ') : '',
      descriptive: [],
      questions: questions,
      sections: [{ direction: null, ids: questions.map(function (q) { return q.id; }) }],
      stats: { questions: questions.length, descriptive: 0, disagreements: 0, flagged: 0, topics: {} }
    };
  }

  function addCurrentAffairsMeta(papers) {
    var topicCounts = {};
    papers.forEach(function (p) {
      p.questions.forEach(function (q) {
        topicCounts[q.topic] = (topicCounts[q.topic] || 0) + 1;
      });
    });
    var existing = {};
    (META.topics || []).forEach(function (t) { existing[t.slug] = t; });
    Object.keys(topicCounts).forEach(function (slug) {
      if (existing[slug]) existing[slug].count += topicCounts[slug];
      else {
        var label = slug.replace(/^ca-/, '').replace(/-/g, ' ')
          .replace(/\b\w/g, function (c) { return c.toUpperCase(); });
        META.topics.push({ slug: slug, label: label, group: 'gk', count: topicCounts[slug], known: true });
      }
    });
    META.topics.sort(function (a, b) { return a.label.localeCompare(b.label); });
    META.totals.papers = (META.totals.papers || 0) + papers.length;
    META.totals.questions = (META.totals.questions || 0) + papers.reduce(function (n, p) { return n + p.questions.length; }, 0);
    META.totals.confidence = META.totals.confidence || { high: 0, medium: 0, low: 0 };
    META.totals.confidence.medium += papers.reduce(function (n, p) { return n + p.questions.length; }, 0);
  }

  async function loadCurrentAffairs() {
    var manifestResponse = await fetch('/data/current-affairs/index.json');
    if (!manifestResponse.ok) throw new Error('current-affairs index ' + manifestResponse.status);
    var manifest = await manifestResponse.json();
    var days = await Promise.all((manifest.days || []).map(async function (entry) {
      var response = await fetch('/data/current-affairs/' + encodeURIComponent(entry.date) + '.json');
      if (!response.ok) throw new Error('current-affairs ' + entry.date + ' ' + response.status);
      return response.json();
    }));
    var papers = days.map(currentAffairsPaper);
    papers.forEach(function (p) { PAPERS.push(p); indexPaper(p); });
    addCurrentAffairsMeta(papers);
  }

  /* ------------------------------------------------------------------ store */

  var DEFAULT_FILTERS = {
    papers: [], topics: [], groups: [],
    status: 'all', confs: [], flaggedOnly: false, disagreeOnly: false,
    shuffle: true
  };

  function loadStore() {
    var base = { v: 1, attempts: {}, tests: [], prefs: { theme: 'auto', filters: null } };
    try {
      var raw = localStorage.getItem(STORE_KEY);
      if (!raw) return base;
      var d = JSON.parse(raw);
      return {
        v: 1,
        attempts: d.attempts || {},
        tests: Array.isArray(d.tests) ? d.tests : [],
        prefs: Object.assign({ theme: 'auto', filters: null }, d.prefs || {})
      };
    } catch (e) {
      console.warn('[ph2] could not read saved progress, starting fresh', e);
      return base;
    }
  }

  var DB = loadStore();

  function save() {
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify(DB));
    } catch (e) {
      toast('Could not save progress — storage may be full');
      console.error('[ph2] save failed', e);
    }
  }

  /* Record one answered question. `choice` is a letter; correct is derived
   * here rather than passed in, so a caller can never record a wrong verdict. */
  function record(key, choice) {
    var q = BY_KEY[key];
    if (!q) return null;
    var ok = choice === q.answer;
    var a = DB.attempts[key] || { n: 0, right: 0, wrong: 0, last: null, lastOk: null, ts: 0 };
    a.n += 1;
    if (ok) a.right += 1; else a.wrong += 1;
    a.last = choice;
    a.lastOk = ok;
    a.ts = Date.now();
    DB.attempts[key] = a;
    return ok;
  }

  function att(key) { return DB.attempts[key] || null; }

  /* ------------------------------------------------------------------ utils */

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  /* Question text uses **word** to mark the word that was underlined in the
   * source paper. For a parts-of-speech question that underline IS the
   * question, so it has to survive all the way to the screen. */
  function qhtml(s) {
    return esc(s).replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>').replace(/\n/g, '<br>');
  }

  function el(html) {
    var d = document.createElement('div');
    d.innerHTML = html.trim();
    return d.firstElementChild;
  }

  function pct(a, b) { return b ? Math.round((a / b) * 100) : 0; }

  function fmtClock(ms) {
    if (ms < 0) ms = 0;
    var t = Math.floor(ms / 1000);
    var h = Math.floor(t / 3600), m = Math.floor((t % 3600) / 60), s = t % 60;
    var pad = function (n) { return n < 10 ? '0' + n : '' + n; };
    return (h ? h + ':' : '') + pad(m) + ':' + pad(s);
  }

  function fmtDate(ts) {
    var d = new Date(ts);
    return d.toLocaleDateString(undefined, { day: 'numeric', month: 'short' }) +
           ' ' + d.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
  }

  function shuffled(arr) {
    var a = arr.slice();
    for (var i = a.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }

  var toastTimer = null;
  function toast(msg) {
    var t = document.getElementById('toast');
    t.textContent = msg;
    t.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { t.hidden = true; }, 2600);
  }

  function markPerQ(paper) { return paper.markPerQuestion || 1; }

  /* --------------------------------------------------------------- filtering */

  var STATUSES = [
    ['all',         'All',                'Every question in the selected papers'],
    ['unattempted', 'Not attempted',      'Questions you have never answered'],
    ['wrong_last',  'Wrong last time',    'Your most recent answer was wrong'],
    ['ever_wrong',  'Ever got wrong',     'You have been wrong at least once, even if right since'],
    ['right_last',  'Right last time',    'Your most recent answer was correct'],
    ['attempted',   'Attempted',          'Any question you have answered at least once']
  ];

  function matches(q, f) {
    if (f.papers.length && f.papers.indexOf(q._paper.paperId) < 0) return false;
    if (f.groups.length && f.groups.indexOf(q.topicGroup) < 0) return false;
    if (f.topics.length && f.topics.indexOf(q.topic) < 0) return false;
    if (f.confs.length && f.confs.indexOf(q.conf) < 0) return false;
    if (f.flaggedOnly && !q.flag) return false;
    if (f.disagreeOnly && !q.disagrees) return false;

    var a = att(q.key);
    switch (f.status) {
      case 'unattempted': return !a;
      case 'attempted':   return !!a;
      case 'wrong_last':  return !!a && a.lastOk === false;
      case 'right_last':  return !!a && a.lastOk === true;
      case 'ever_wrong':  return !!a && a.wrong > 0;
      default:            return true;
    }
  }

  function select(f) { return ALL.filter(function (q) { return matches(q, f); }); }

  /* ----------------------------------------------------------------- state */

  var S = {
    view: 'dash',
    openPapers: {},
    revealed: {},
    filters: Object.assign({}, DEFAULT_FILTERS, DB.prefs.filters || {}),
    drill: null,
    mock: null
  };

  function setFilters(patch) {
    Object.assign(S.filters, patch);
    DB.prefs.filters = S.filters;
    save();
  }

  function toggleIn(list, val) {
    var i = list.indexOf(val);
    if (i < 0) list.push(val); else list.splice(i, 1);
    return list;
  }

  /* ------------------------------------------------- question card (shared) */

  /* One renderer for every context: browse, drill, mock, review. `mode`
   * decides how much is shown. Extending this beats duplicating card markup
   * in four views — the same lesson QuestionCard taught in the React app. */
  function questionCard(q, opts) {
    opts = opts || {};
    var mode = opts.mode || 'browse';          // browse | quiz | result
    var picked = opts.picked || null;
    var revealed = opts.revealed || mode === 'result';
    var num = opts.num != null ? opts.num : q.n;

    var c = document.createElement('div');
    c.className = 'q' + (opts.flat ? ' flat' : '');
    c.dataset.key = q.key;

    var a = att(q.key);
    var tags = [];
    if (opts.showPaper) {
      tags.push('<span class="pill acc">' + esc(q._paper.examShort + ' ' + q._paper.paper) + '</span>');
    }
    tags.push('<span class="pill">' + esc(q.topicLabel) + '</span>');
    if (q.flag) tags.push('<span class="pill no">flagged</span>');
    if (q.disagrees && revealed) tags.push('<span class="pill wn">differs from marked key</span>');
    if (a) {
      tags.push('<span class="pill ' + (a.lastOk ? 'ok' : 'no') + '">' +
        (a.lastOk ? 'last: correct' : 'last: wrong') +
        (a.n > 1 ? ' · ' + a.n + ' tries' : '') + '</span>');
    }

    var head =
      '<div class="q-top">' +
        '<span class="q-n">' + esc(num) + '</span>' +
        '<div class="q-text">' + qhtml(q.q) +
          '<div class="q-tags">' + tags.join('') + '</div>' +
        '</div>' +
      '</div>';

    var fig = q.figure
      ? '<div class="q-figure"><strong>Figure (described — the source is an image)</strong>' +
        esc(q.figure) + '</div>'
      : '';

    c.innerHTML = head + fig + '<div class="opts"></div>';

    var optsBox = c.querySelector('.opts');
    LETTERS.forEach(function (L) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'opt';
      b.dataset.letter = L;

      var cls = '';
      if (revealed) {
        if (L === q.answer) cls = 'right';
        else if (picked === L) cls = 'wrong';
      } else if (picked === L) {
        cls = 'picked';
      }
      if (cls) b.classList.add(cls);

      var mk = '';
      if (revealed && q.marked === L && q.marked !== q.answer) {
        mk = '<span class="mk">marked in source</span>';
      }
      b.innerHTML = '<span class="L">(' + L + ')</span><span>' + esc(q.opts[L]) + '</span>' + mk;

      if (mode === 'quiz' && !revealed) {
        b.addEventListener('click', function () { opts.onPick && opts.onPick(L); });
      } else {
        b.disabled = true;
      }
      optsBox.appendChild(b);
    });

    if (revealed) c.appendChild(answerBox(q));
    else if (mode === 'browse') {
      var btn = el('<button class="btn sm" style="margin-top:.6rem">Show answer</button>');
      btn.addEventListener('click', function () {
        S.revealed[q.key] = true;
        btn.replaceWith(answerBox(q));
      });
      c.appendChild(btn);
    }
    return c;
  }

  /* The provenance line. `derived` is not decoration — there is genuinely no
   * official MPSC key for any of these sittings, and the confidence is the
   * solver's own honest rating, so an unrated answer must never look
   * authoritative by omission. */
  function provPill(q) {
    var conf = q.conf || 'low';
    var label = 'derived · ' + (q.conf ? conf : 'unrated');
    return '<span class="prov ' + esc(conf) + '">' + esc(label) + '</span>';
  }

  function answerBox(q) {
    var box = document.createElement('div');
    box.className = 'q-ans';
    var html =
      '<div class="hdr">' +
        '<strong>Answer: (' + esc(q.answer) + ')</strong> ' +
        provPill(q) +
      '</div>' +
      '<div class="why">' + qhtml(q.why || '') + '</div>';

    if (q.disagrees) {
      html += '<div class="disagree"><strong>Disagreement with the source PDF.</strong> ' +
        'The option highlighted in the paper was <strong>(' + esc(q.marked) + ')</strong>, ' +
        'but the answer above is <strong>(' + esc(q.answer) + ')</strong>. Those highlights are ' +
        'someone’s marked answers, not an official MPSC key, and they are known to contain ' +
        'errors — so read the reasoning and decide for yourself.</div>';
    }
    if (q.flag) {
      html += '<div class="flagbox"><strong>Problem with this question:</strong> ' +
        esc(q.flag) + '</div>';
    }
    box.innerHTML = html;
    return box;
  }

  function descriptiveCard(d) {
    var c = document.createElement('div');
    c.className = 'desc';
    var kind = (d.kind || '').replace(/_/g, ' ');
    var html = '<div class="kind">' + esc(kind) + (d.marks ? ' · ' + d.marks + ' marks' : '') + '</div>';
    if (d.prompt) html += '<div style="margin-top:.3rem">' + qhtml(d.prompt) + '</div>';
    if (d.choices && d.choices.length) {
      html += '<ul style="margin:.4rem 0 0;padding-left:1.2rem">' +
        d.choices.map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>';
    }
    if (d.passage) html += '<div class="passage">' + qhtml(d.passage) + '</div>';
    if (d.guidance) {
      html += '<div class="guidance"><strong>How to answer this</strong>' + qhtml(d.guidance) + '</div>';
    }
    c.innerHTML = html;
    return c;
  }

  /* -------------------------------------------------------------- dashboard */

  function viewDash() {
    var main = document.getElementById('main');
    var t = META.totals || {};
    var attempted = 0, wrongNow = 0, everWrong = 0, rightNow = 0;
    ALL.forEach(function (q) {
      var a = att(q.key);
      if (!a) return;
      attempted++;
      if (a.lastOk) rightNow++; else wrongNow++;
      if (a.wrong > 0) everWrong++;
    });

    var html = '';
    html += '<div class="page-head"><h1>Dashboard</h1><p>' +
      esc(t.questions || 0) + ' solved questions across ' + esc(t.papers || 0) +
      ' papers and current-affairs sets. Every answer here is derived — none of these sets has a ' +
      'published official key — so each one carries its own confidence rating.</p></div>';

    html += '<div class="grid g4">' +
      stat('Questions', t.questions || 0, esc(t.papers || 0) + ' papers') +
      stat('Attempted', attempted, pct(attempted, ALL.length) + '% of the bank') +
      stat('Wrong right now', wrongNow, 'last answer was wrong', wrongNow ? 'bad' : '') +
      stat('Ever wrong', everWrong, 'includes ones you have since fixed', 'warn') +
      '</div>';

    html += '<div class="grid g2 mt">';

    html += '<div class="card"><h2>Pick up where it hurts</h2>' +
      '<p class="dim">The whole point of tracking attempts is to stop re-drilling what you ' +
      'already know. These jump straight into a drill with the filter pre-set.</p>' +
      '<div class="row mt">' +
      '<button class="btn pri" data-go="wrong_last"' + (wrongNow ? '' : ' disabled') + '>' +
        'Drill wrong answers (' + wrongNow + ')</button>' +
      '<button class="btn" data-go="ever_wrong"' + (everWrong ? '' : ' disabled') + '>' +
        'Ever wrong (' + everWrong + ')</button>' +
      '<button class="btn" data-go="unattempted">Fresh questions (' + (ALL.length - attempted) + ')</button>' +
      '</div></div>';

    html += '<div class="card"><h2>Answer quality</h2>' +
      '<p class="dim">Confidence is the solver’s own honest rating, not a score. ' +
      'Medium and low are the ones worth a second human look.</p>';
    var cf = t.confidence || { high: 0, medium: 0, low: 0 };
    var cft = (cf.high || 0) + (cf.medium || 0) + (cf.low || 0);
    html += confRow('High confidence', cf.high || 0, cft, 'good') +
            confRow('Medium', cf.medium || 0, cft, 'warn') +
            confRow('Low', cf.low || 0, cft, 'bad');
    html += '<hr class="sep">' +
      '<div class="row">' +
      '<button class="btn sm" data-review="disagree">' + esc(t.disagreements || 0) +
        ' differ from the marked key</button>' +
      '<button class="btn sm" data-review="flagged">' + esc(t.flagged || 0) +
        ' flagged as defective</button>' +
      '</div></div>';

    html += '</div>';

    // Per-paper coverage
    html += '<div class="card mt"><h2>Coverage by paper</h2><div class="scroll-x"><table>' +
      '<thead><tr><th>Paper</th><th class="num">Qs</th><th class="num">Attempted</th>' +
      '<th class="num">Accuracy</th><th style="width:130px"></th><th></th></tr></thead><tbody>';
    PAPERS.forEach(function (p) {
      var qs = p.questions || [], done = 0, ok = 0;
      qs.forEach(function (q) {
        var a = att(q.key);
        if (a) { done++; if (a.lastOk) ok++; }
      });
      html += '<tr>' +
        '<td><strong>' + esc(p.examShort + ' ' + p.paper) + '</strong><br>' +
          '<span class="dim">' + esc(p.paperTitle + ' · ' + p.sitting) + '</span></td>' +
        '<td class="num">' + qs.length + '</td>' +
        '<td class="num">' + done + '</td>' +
        '<td class="num">' + (done ? pct(ok, done) + '%' : '—') + '</td>' +
        '<td><div class="bar"><i style="width:' + pct(done, qs.length) + '%"></i></div></td>' +
        '<td><button class="btn sm" data-openpaper="' + esc(p.paperId) + '">Browse</button></td>' +
        '</tr>';
    });
    html += '</tbody></table></div></div>';

    if (DB.tests.length) {
      html += '<div class="card mt"><h2>Recent tests</h2><div class="scroll-x"><table>' +
        '<thead><tr><th>When</th><th>Test</th><th class="num">Score</th>' +
        '<th class="num">Correct</th><th class="num">Accuracy</th></tr></thead><tbody>';
      DB.tests.slice(0, 6).forEach(function (r) {
        html += '<tr><td>' + esc(fmtDate(r.ts)) + '</td><td>' + esc(r.label) + '</td>' +
          '<td class="num">' + esc(r.score.toFixed(2)) + ' / ' + esc(r.maxScore) + '</td>' +
          '<td class="num">' + r.correct + '/' + r.total + '</td>' +
          '<td class="num">' + pct(r.correct, r.answered || 1) + '%</td></tr>';
      });
      html += '</tbody></table></div></div>';
    }

    main.innerHTML = html;

    main.querySelectorAll('[data-go]').forEach(function (b) {
      b.addEventListener('click', function () {
        setFilters({ papers: [], topics: [], groups: [], confs: [],
                     flaggedOnly: false, disagreeOnly: false, status: b.dataset.go });
        startDrill();
      });
    });
    main.querySelectorAll('[data-review]').forEach(function (b) {
      b.addEventListener('click', function () { go('review', b.dataset.review); });
    });
    main.querySelectorAll('[data-openpaper]').forEach(function (b) {
      b.addEventListener('click', function () {
        S.openPapers[b.dataset.openpaper] = true;
        go('papers');
        var node = document.querySelector('[data-paper="' + b.dataset.openpaper + '"]');
        if (node) node.scrollIntoView({ behavior: 'smooth', block: 'start' });
      });
    });
  }

  function stat(k, v, s, cls) {
    return '<div class="stat ' + (cls || '') + '"><div class="k">' + esc(k) + '</div>' +
      '<div class="v">' + esc(v) + '</div><div class="s">' + esc(s || '') + '</div></div>';
  }

  function confRow(label, n, total, cls) {
    return '<div style="margin-bottom:.55rem"><div class="spread">' +
      '<span style="font-size:.86rem">' + esc(label) + '</span>' +
      '<span class="dim">' + n + '</span></div>' +
      '<div class="bar ' + cls + '"><i style="width:' + pct(n, total) + '%"></i></div></div>';
  }

  /* ----------------------------------------------------------- browse view */

  function viewPapers() {
    var main = document.getElementById('main');
    main.innerHTML =
      '<div class="page-head"><h1>Browse Papers</h1><p>Grouped the way MPSC actually ' +
      'prints them — exam, sitting, paper. Expand one to read every question inline ' +
      'with its answer and reasoning; you do not have to start a test to study.</p></div>' +
      '<div id="paperList"></div>';

    var list = document.getElementById('paperList');
    var lastSitting = null;

    PAPERS.forEach(function (p) {
      if (p.sittingLabel !== lastSitting) {
        lastSitting = p.sittingLabel;
        list.appendChild(el('<h2 class="mt">' + esc(p.sittingLabel) + '</h2>'));
        list.appendChild(el('<p class="dim" style="margin-top:-.3rem">' + esc(p.dept || '') + '</p>'));
      }
      list.appendChild(paperCard(p));
    });
  }

  function paperCard(p) {
    var open = !!S.openPapers[p.paperId];
    var card = document.createElement('div');
    card.className = 'paper-card' + (open ? ' open' : '');
    card.dataset.paper = p.paperId;

    var st = p.stats || {};
    var done = 0, ok = 0;
    (p.questions || []).forEach(function (q) {
      var a = att(q.key);
      if (a) { done++; if (a.lastOk) ok++; }
    });

    var sub = [
      esc(p.paperTitle),
      st.questions + ' MCQs',
      st.descriptive ? st.descriptive + ' written items' : null,
      // not every booklet prints a series letter; 'Series ' is truthy even when
      // the letter is null, so filter(Boolean) below cannot catch it
      p.series ? 'Series ' + esc(p.series) : null,
      p.maxMarks + ' marks · ' + p.durationMin + ' min',
      done ? done + ' attempted · ' + pct(ok, done) + '% right' : 'not attempted'
    ].filter(Boolean).join(' · ');

    // The whole header row is the expand target, but it still has to be a real
    // control: focusable, announced as a button, and reporting its own state.
    var head = el(
      '<div class="paper-head" role="button" tabindex="0" aria-expanded="' + open + '"' +
        ' aria-label="' + esc(p.paper + ' — ' + p.paperTitle + ', ' +
          (open ? 'collapse' : 'expand')) + '">' +
        '<span class="chev" aria-hidden="true">' + (open ? '▾' : '▸') + '</span>' +
        '<span class="ttl"><strong>' + esc(p.paper) + ' — ' + esc(p.paperTitle) + '</strong>' +
          '<span>' + sub + '</span></span>' +
        '<span class="acts">' +
          '<button class="btn sm" data-act="reveal">Reveal all</button>' +
          '<button class="btn sm pri" data-act="mock">Start full mock</button>' +
        '</span>' +
      '</div>');

    function toggle() {
      S.openPapers[p.paperId] = !S.openPapers[p.paperId];
      card.replaceWith(paperCard(p));
    }

    head.addEventListener('click', function (ev) {
      if (ev.target.closest('[data-act]')) return;
      toggle();
    });
    head.addEventListener('keydown', function (ev) {
      if (ev.target.closest('[data-act]')) return;
      if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); toggle(); }
    });
    head.querySelector('[data-act="mock"]').addEventListener('click', function (ev) {
      ev.stopPropagation();
      startMock({ mode: 'paper', paper: p });
    });
    head.querySelector('[data-act="reveal"]').addEventListener('click', function (ev) {
      ev.stopPropagation();
      (p.questions || []).forEach(function (q) { S.revealed[q.key] = true; });
      S.openPapers[p.paperId] = true;
      card.replaceWith(paperCard(p));
    });

    card.appendChild(head);
    if (open) card.appendChild(paperBody(p));
    return card;
  }

  function paperBody(p) {
    var body = document.createElement('div');
    body.className = 'paper-body';

    var desc = p.descriptive || [];
    if (desc.length) {
      body.appendChild(el('<div class="section-head">Part A — conventional / written ' +
        '(' + desc.length + ' items). These cannot be drilled as MCQs; read them and ' +
        'practise them longhand.</div>'));
      desc.forEach(function (d) { body.appendChild(descriptiveCard(d)); });
    }

    var qs = p.questions || [];
    if (qs.length) {
      body.appendChild(el('<div class="section-head">Objective / MCQ — ' + qs.length +
        ' questions</div>'));
    }

    // Sections come from the data (runs of shared `direction`), so a paper with
    // a different set of direction blocks needs no code change here.
    var byId = {};
    qs.forEach(function (q) { byId[q.id] = q; });
    (p.sections || []).forEach(function (sec) {
      if (sec.direction) {
        body.appendChild(el('<div class="section-head">Direction: ' +
          esc(sec.direction) + '</div>'));
      }
      sec.ids.forEach(function (id) {
        var q = byId[id];
        if (!q) return;
        body.appendChild(questionCard(q, {
          mode: 'browse',
          revealed: !!S.revealed[q.key],
          num: q.part === 'A' ? q.id : q.n
        }));
      });
    });

    body.appendChild(el('<p class="dim mt">Source: <code>' + esc(p.sourcePdf) +
      '</code>' + (p.series ? ' — Question Booklet Series ' + esc(p.series) : '') +
      '.</p>'));
    return body;
  }

  /* --------------------------------------------------------- practice view */

  function viewPractice() {
    var main = document.getElementById('main');
    if (S.drill) return renderDrill();

    main.innerHTML =
      '<div class="page-head"><h1>Practice</h1><p>Build a set, then drill it one question ' +
      'at a time with instant feedback. The status filter is the useful one: it reads your ' +
      'own attempt history, so <em>Wrong last time</em> and <em>Not attempted</em> shrink as ' +
      'you work.</p></div>' +
      '<div class="card" id="filterPanel"></div>' +
      '<div class="card mt" id="filterResult"></div>';

    renderFilters(document.getElementById('filterPanel'), function () {
      renderFilterResult();
    });
    renderFilterResult();
  }

  function renderFilterResult() {
    var box = document.getElementById('filterResult');
    if (!box) return;
    var picked = select(S.filters);
    var byPaper = {};
    picked.forEach(function (q) {
      byPaper[q._paper.paperId] = (byPaper[q._paper.paperId] || 0) + 1;
    });

    var breakdown = PAPERS.filter(function (p) { return byPaper[p.paperId]; })
      .map(function (p) {
        return '<span class="pill">' + esc(p.examShort + ' ' + p.paper) + ' · ' +
          byPaper[p.paperId] + '</span>';
      }).join(' ');

    box.innerHTML =
      '<div class="spread"><h2 style="margin:0">' + picked.length +
        ' question' + (picked.length === 1 ? '' : 's') + ' selected</h2>' +
        '<label class="dim" style="cursor:pointer"><input type="checkbox" id="shuf"' +
        (S.filters.shuffle ? ' checked' : '') + '> shuffle order</label></div>' +
      (breakdown ? '<div class="row mt">' + breakdown + '</div>' : '') +
      '<div class="row mt">' +
        '<button class="btn pri" id="startDrill"' + (picked.length ? '' : ' disabled') + '>' +
          'Start drill</button>' +
        '<button class="btn" id="startCustom"' + (picked.length ? '' : ' disabled') + '>' +
          'Make a timed mock from these</button>' +
        '<button class="btn" id="readList"' + (picked.length ? '' : ' disabled') + '>' +
          'Read them with answers</button>' +
      '</div>' +
      (picked.length ? '' : '<p class="dim mt">Nothing matches. If you picked ' +
        '<em>Wrong last time</em> and it is empty, that is the good outcome.</p>');

    var sh = document.getElementById('shuf');
    if (sh) sh.addEventListener('change', function () { setFilters({ shuffle: sh.checked }); });
    var sd = document.getElementById('startDrill');
    if (sd) sd.addEventListener('click', function () { startDrill(); });
    var sc = document.getElementById('startCustom');
    if (sc) sc.addEventListener('click', function () { customMockDialog(picked); });
    var rl = document.getElementById('readList');
    if (rl) rl.addEventListener('click', function () { readList(picked); });
  }

  function isCurrentAffairsQuestion(q) {
    return q && q._paper && q._paper.paperId.indexOf('current-affairs-') === 0;
  }

  function currentAffairsQuestions() {
    return ALL.filter(isCurrentAffairsQuestion);
  }

  /* A single entry point for the daily archive. The Browse Papers view is
   * deliberately answer-first; this tab is the tappable exam-drill surface. */
  function viewCurrentAffairs() {
    var main = document.getElementById('main');
    var qs = currentAffairsQuestions();
    var attempted = qs.filter(function (q) { return !!att(q.key); }).length;
    var wrong = qs.filter(function (q) { var a = att(q.key); return a && !a.lastOk; }).length;
    var dates = {};
    qs.forEach(function (q) {
      var p = q._paper;
      dates[p.paper] = dates[p.paper] || { p: p, n: 0, done: 0 };
      dates[p.paper].n++;
      if (att(q.key)) dates[p.paper].done++;
    });

    main.innerHTML =
      '<div class="page-head"><h1>Current Affairs</h1><p>All daily and weekly current-affairs MCQs in one exam-drill pool. Tap an option to answer; explanations appear after each choice.</p></div>' +
      '<div class="grid g4">' +
        stat('Questions', qs.length, Object.keys(dates).length + ' dated sets') +
        stat('Attempted', attempted, pct(attempted, qs.length) + '% of current affairs') +
        stat('Wrong last time', wrong, 'ready to re-drill', wrong ? 'bad' : '') +
        stat('Unattempted', qs.length - attempted, 'fresh questions') +
      '</div>' +
      '<div class="card mt"><h2>Exam drill</h2><p class="dim">This combines every current-affairs file currently in the archive. Your progress is saved separately for each question.</p><div class="row mt">' +
        '<button class="btn pri" id="caDrill">Start all-current-affairs drill</button>' +
        '<button class="btn" id="caMock">Take timed current-affairs mock</button>' +
        '<button class="btn" id="caWrong"' + (wrong ? '' : ' disabled') + '>Drill wrong last time (' + wrong + ')</button>' +
      '</div></div>' +
      '<div class="card mt"><h2>Dated sets</h2><div class="scroll-x"><table><thead><tr><th>Date</th><th>Source set</th><th class="num">Questions</th><th class="num">Attempted</th></tr></thead><tbody>' +
      Object.keys(dates).sort().reverse().map(function (date) {
        var d = dates[date];
        return '<tr><td><strong>' + esc(date) + '</strong></td><td>' + esc(d.p.paperTitle) + '</td><td class="num">' + d.n + '</td><td class="num">' + d.done + '</td></tr>';
      }).join('') +
      '</tbody></table></div></div>';

    function setCurrentAffairsFilters(status) {
      setFilters({
        papers: Object.keys(dates).map(function (date) { return dates[date].p.paperId; }),
        topics: [], groups: [], confs: [], flaggedOnly: false, disagreeOnly: false,
        status: status || 'all', shuffle: true
      });
    }
    document.getElementById('caDrill').addEventListener('click', function () {
      setCurrentAffairsFilters('all'); startDrill();
    });
    document.getElementById('caMock').addEventListener('click', function () {
      customMockDialog(qs);
    });
    document.getElementById('caWrong').addEventListener('click', function () {
      setCurrentAffairsFilters('wrong_last'); startDrill();
    });
  }

  function renderFilters(box, onChange) {
    var f = S.filters;

    function chips(label, items, isOn, onClick, help) {
      var h = '<div class="fgroup"><div class="flabel">' + esc(label) + '</div>' +
        (help ? '<p class="dim" style="margin:-.15rem 0 .35rem">' + esc(help) + '</p>' : '') +
        '<div class="chips">';
      items.forEach(function (it, i) {
        h += '<button class="chip' + (isOn(it) ? ' on' : '') + '" data-grp="' +
          esc(label) + '" data-i="' + i + '">' + esc(it.label) +
          (it.count != null ? '<span class="c">' + it.count + '</span>' : '') + '</button>';
      });
      return h + '</div></div>';
    }

    var statusItems = STATUSES.map(function (s) {
      var n = ALL.filter(function (q) {
        return matches(q, Object.assign({}, f, { status: s[0] }));
      }).length;
      return { key: s[0], label: s[1], count: n, help: s[2] };
    });

    var paperItems = PAPERS.map(function (p) {
      return { key: p.paperId, label: p.examShort + ' ' + p.paper, count: (p.questions || []).length };
    });

    var groupItems = (META.groups || []).map(function (g) {
      var n = ALL.filter(function (q) { return q.topicGroup === g.slug; }).length;
      return { key: g.slug, label: g.label, count: n };
    }).filter(function (g) { return g.count > 0; });

    var topicItems = (META.topics || []).filter(function (t) {
      return !f.groups.length || f.groups.indexOf(t.group) >= 0;
    }).map(function (t) {
      return { key: t.slug, label: t.label, count: t.count };
    });

    var confItems = [
      { key: 'high', label: 'High' }, { key: 'medium', label: 'Medium' }, { key: 'low', label: 'Low' }
    ];

    var html = '<div class="filters">';
    html += chips('Status', statusItems, function (i) { return f.status === i.key; }, null,
      statusItems.filter(function (s) { return s.key === f.status; })[0].help);
    html += chips('Paper', paperItems, function (i) { return f.papers.indexOf(i.key) >= 0; }, null,
      'No selection means every paper.');
    html += chips('Subject', groupItems, function (i) { return f.groups.indexOf(i.key) >= 0; });
    if (topicItems.length) {
      html += chips('Topic', topicItems, function (i) { return f.topics.indexOf(i.key) >= 0; }, null,
        f.groups.length ? 'Topics within the selected subjects.' : '');
    }
    html += chips('Answer confidence', confItems, function (i) { return f.confs.indexOf(i.key) >= 0; }, null,
      'Low-confidence answers are the ones the solver was least sure of.');
    html += '<div class="fgroup"><div class="flabel">Only show</div><div class="chips">' +
      '<button class="chip' + (f.flaggedOnly ? ' on' : '') + '" data-only="flag">' +
        'Flagged as defective</button>' +
      '<button class="chip' + (f.disagreeOnly ? ' on' : '') + '" data-only="dis">' +
        'Differs from marked key</button>' +
      '<button class="chip" data-only="reset">Reset all filters</button>' +
      '</div></div>';
    html += '</div>';
    box.innerHTML = html;

    var maps = {
      'Status': [statusItems, function (it) { setFilters({ status: it.key }); }],
      'Paper': [paperItems, function (it) { setFilters({ papers: toggleIn(f.papers, it.key) }); }],
      'Subject': [groupItems, function (it) {
        var g = toggleIn(f.groups, it.key);
        // Drop topic picks that no longer belong to any selected subject,
        // otherwise the two filters silently contradict each other and you get
        // an empty set with no visible reason why.
        var keep = f.topics.filter(function (slug) {
          var t = (META.topics || []).filter(function (x) { return x.slug === slug; })[0];
          return !g.length || (t && g.indexOf(t.group) >= 0);
        });
        setFilters({ groups: g, topics: keep });
      }],
      'Topic': [topicItems, function (it) { setFilters({ topics: toggleIn(f.topics, it.key) }); }],
      'Answer confidence': [confItems, function (it) { setFilters({ confs: toggleIn(f.confs, it.key) }); }]
    };

    box.querySelectorAll('[data-grp]').forEach(function (b) {
      b.addEventListener('click', function () {
        var m = maps[b.dataset.grp];
        m[1](m[0][+b.dataset.i]);
        renderFilters(box, onChange);
        onChange();
      });
    });
    box.querySelectorAll('[data-only]').forEach(function (b) {
      b.addEventListener('click', function () {
        var k = b.dataset.only;
        if (k === 'flag') setFilters({ flaggedOnly: !f.flaggedOnly });
        else if (k === 'dis') setFilters({ disagreeOnly: !f.disagreeOnly });
        else setFilters(JSON.parse(JSON.stringify(DEFAULT_FILTERS)));
        renderFilters(box, onChange);
        onChange();
      });
    });
  }

  function readList(qs) {
    var main = document.getElementById('main');
    main.innerHTML = '<div class="page-head"><h1>' + qs.length +
      ' questions</h1><p>Filtered set, answers shown.</p></div>' +
      '<div class="row" style="margin-bottom:1rem"><button class="btn" id="back">' +
      '← Back to filters</button></div><div id="rl"></div>';
    var box = document.getElementById('rl');
    qs.forEach(function (q, i) {
      box.appendChild(questionCard(q, { mode: 'result', num: i + 1, showPaper: true }));
    });
    document.getElementById('back').addEventListener('click', function () { go('practice'); });
  }

  /* --------------------------------------------------------------- drill */

  function startDrill() {
    var qs = select(S.filters);
    if (!qs.length) { toast('Nothing matches that filter'); return; }
    if (S.filters.shuffle) qs = shuffled(qs);
    S.drill = { keys: qs.map(function (q) { return q.key; }), i: 0, picked: {}, right: 0, wrong: 0 };
    go('practice');
  }

  function renderDrill() {
    var main = document.getElementById('main');
    var d = S.drill;
    if (d.i >= d.keys.length) return renderDrillDone();

    var q = BY_KEY[d.keys[d.i]];
    var picked = d.picked[q.key] || null;

    main.innerHTML =
      '<div class="drill-bar">' +
        '<div class="prog"><div class="spread"><strong style="font-size:.86rem">Question ' +
          (d.i + 1) + ' of ' + d.keys.length + '</strong>' +
          '<span class="dim">' + d.right + ' right · ' + d.wrong + ' wrong</span></div>' +
          '<div class="bar"><i style="width:' + pct(d.i, d.keys.length) + '%"></i></div></div>' +
        '<span class="pill acc">' + esc(q._paper.examShort + ' ' + q._paper.paper + ' Q' + q.n) + '</span>' +
        '<button class="btn sm" id="skip">Skip</button>' +
        '<button class="btn sm danger" id="quit">End drill</button>' +
      '</div>' +
      '<div id="drillQ"></div>' +
      '<div class="row mt" id="drillNav"></div>';

    var host = document.getElementById('drillQ');
    host.appendChild(questionCard(q, {
      mode: 'quiz',
      picked: picked,
      revealed: !!picked,
      showPaper: false,
      onPick: function (L) {
        var ok = record(q.key, L);
        d.picked[q.key] = L;
        if (ok) d.right++; else d.wrong++;
        save();
        renderDrill();
      }
    }));

    var nav = document.getElementById('drillNav');
    if (picked) {
      var next = el('<button class="btn pri">' +
        (d.i + 1 >= d.keys.length ? 'See summary' : 'Next question →') + '</button>');
      next.addEventListener('click', function () { d.i++; renderDrill(); });
      nav.appendChild(next);
      nav.appendChild(el('<span class="dim">or press Enter</span>'));
    } else {
      nav.appendChild(el('<span class="dim">Pick an option to see the answer and reasoning.</span>'));
    }

    document.getElementById('skip').addEventListener('click', function () { d.i++; renderDrill(); });
    document.getElementById('quit').addEventListener('click', function () {
      S.drill = null; go('practice');
    });
  }

  function renderDrillDone() {
    var d = S.drill;
    var answered = d.right + d.wrong;
    var wrongQs = Object.keys(d.picked).filter(function (k) {
      return d.picked[k] !== BY_KEY[k].answer;
    });

    var main = document.getElementById('main');
    main.innerHTML =
      '<div class="page-head"><h1>Drill finished</h1><p>' + answered + ' of ' + d.keys.length +
      ' answered.</p></div>' +
      '<div class="grid g3">' +
        stat('Correct', d.right, pct(d.right, answered || 1) + '% of answered', 'good') +
        stat('Wrong', d.wrong, wrongQs.length ? 'listed below' : '', d.wrong ? 'bad' : '') +
        stat('Skipped', d.keys.length - answered, '') +
      '</div>' +
      '<div class="row mt">' +
        '<button class="btn pri" id="again">Back to filters</button>' +
        (wrongQs.length ? '<button class="btn" id="redo">Re-drill the ' + wrongQs.length +
          ' you got wrong</button>' : '') +
      '</div>' +
      (wrongQs.length ? '<h2 class="mt">What you got wrong</h2><div id="wrongList"></div>' : '');

    if (wrongQs.length) {
      var box = document.getElementById('wrongList');
      wrongQs.forEach(function (k, i) {
        box.appendChild(questionCard(BY_KEY[k], {
          mode: 'result', picked: d.picked[k], num: i + 1, showPaper: true
        }));
      });
      document.getElementById('redo').addEventListener('click', function () {
        S.drill = { keys: wrongQs.slice(), i: 0, picked: {}, right: 0, wrong: 0 };
        renderDrill();
        window.scrollTo(0, 0);
      });
    }
    document.getElementById('again').addEventListener('click', function () {
      S.drill = null; go('practice');
    });
  }

  /* ----------------------------------------------------------- mock tests */

  function viewMock() {
    if (S.mock && !S.mock.submitted) return renderMockRun();
    if (S.mock && S.mock.submitted) return renderMockResult();

    var main = document.getElementById('main');
    var html =
      '<div class="page-head"><h1>Mock Test</h1><p>Full-paper mocks use the real duration, ' +
      'the real mark-per-question and the real negative marking printed on the booklet, so ' +
      'the score you see is the score you would have got.</p></div>';

    html += '<div id="mockCards"></div>';
    html += '<div class="card mt"><h2>Custom test</h2>' +
      '<p class="dim">Build any set on the Practice tab — by topic, or only the ones you ' +
      'got wrong — then turn it into a timed test from there.</p>' +
      '<button class="btn mt" id="toPractice">Go to Practice filters</button></div>';

    if (DB.tests.length) {
      html += '<div class="card mt"><h2>Test history</h2><div class="scroll-x"><table>' +
        '<thead><tr><th>When</th><th>Test</th><th class="num">Score</th><th class="num">Right</th>' +
        '<th class="num">Wrong</th><th class="num">Skipped</th><th class="num">Time</th>' +
        '<th></th></tr></thead><tbody>';
      DB.tests.forEach(function (r, i) {
        html += '<tr><td>' + esc(fmtDate(r.ts)) + '</td><td>' + esc(r.label) + '</td>' +
          '<td class="num"><strong>' + esc(r.score.toFixed(2)) + '</strong> / ' + esc(r.maxScore) + '</td>' +
          '<td class="num">' + r.correct + '</td><td class="num">' + r.wrong + '</td>' +
          '<td class="num">' + (r.total - r.answered) + '</td>' +
          '<td class="num">' + esc(fmtClock(r.durationMs)) + '</td>' +
          '<td><button class="btn sm" data-hist="' + i + '">Review</button></td></tr>';
      });
      html += '</tbody></table></div></div>';
    }

    main.innerHTML = html;

    var cards = document.getElementById('mockCards');
    var lastSitting = null;
    PAPERS.forEach(function (p) {
      if (p.sittingLabel !== lastSitting) {
        lastSitting = p.sittingLabel;
        cards.appendChild(el('<h2 class="mt">' + esc(p.sittingLabel) + '</h2>'));
      }
      var mq = markPerQ(p);
      var qn = (p.questions || []).length;
      var c = el('<div class="paper-card"><div class="paper-head">' +
        '<span class="ttl"><strong>' + esc(p.paper + ' — ' + p.paperTitle) + '</strong>' +
        '<span>' + qn + ' MCQs × ' + mq + ' mark' + (mq === 1 ? '' : 's') +
        ' = ' + (qn * mq) + ' marks · ' + p.durationMin + ' min · ' +
        '−' + (mq * (p.negativeMark || 0)).toFixed(2) + ' per wrong answer</span></span>' +
        '<span class="acts"><button class="btn pri" data-start="' + esc(p.paperId) +
        '">Start</button></span></div></div>');
      c.querySelector('[data-start]').addEventListener('click', function () {
        startMock({ mode: 'paper', paper: p });
      });
      cards.appendChild(c);
    });

    var tp = document.getElementById('toPractice');
    if (tp) tp.addEventListener('click', function () { go('practice'); });
    main.querySelectorAll('[data-hist]').forEach(function (b) {
      b.addEventListener('click', function () { reviewHistoric(DB.tests[+b.dataset.hist]); });
    });
  }

  function customMockDialog(qs) {
    var maxN = qs.length;
    var defN = Math.min(25, maxN);
    openModal(
      '<h2>Timed test from your filter</h2>' +
      '<p class="dim">' + maxN + ' questions match. Marking follows the paper each question ' +
      'came from, so a mixed set can score in fractions.</p>' +
      '<div class="row mt"><label>Questions <input type="number" id="cN" min="1" max="' +
        maxN + '" value="' + defN + '" style="width:5.5rem"></label>' +
      '<label>Minutes <input type="number" id="cM" min="1" max="300" value="' +
        Math.max(1, Math.round(defN * 1.2)) + '" style="width:5.5rem"></label></div>' +
      '<div class="row mt"><button class="btn pri" id="cGo">Start test</button>' +
      '<button class="btn" id="cX">Cancel</button></div>',
      function (body) {
        body.querySelector('#cGo').addEventListener('click', function () {
          var n = Math.max(1, Math.min(maxN, +body.querySelector('#cN').value || defN));
          var m = Math.max(1, +body.querySelector('#cM').value || 30);
          closeModal();
          startMock({ mode: 'custom', questions: shuffled(qs).slice(0, n), minutes: m });
        });
        body.querySelector('#cX').addEventListener('click', closeModal);
      }
    );
  }

  function startMock(cfg) {
    var qs, minutes, label, maxScore;
    if (cfg.mode === 'paper') {
      qs = (cfg.paper.questions || []).slice();
      minutes = cfg.paper.durationMin;
      label = cfg.paper.examShort + ' ' + cfg.paper.paper + ' (' + cfg.paper.sitting + ') — full paper';
      maxScore = qs.length * markPerQ(cfg.paper);
    } else {
      qs = cfg.questions;
      minutes = cfg.minutes;
      label = 'Custom · ' + qs.length + ' questions';
      maxScore = qs.reduce(function (s, q) { return s + markPerQ(q._paper); }, 0);
    }
    if (!qs.length) { toast('No questions to test'); return; }

    S.mock = {
      keys: qs.map(function (q) { return q.key; }),
      i: 0, answers: {}, review: {},
      startedAt: Date.now(),
      endsAt: Date.now() + minutes * 60000,
      minutes: minutes, label: label, maxScore: maxScore,
      mode: cfg.mode, paperId: cfg.paper ? cfg.paper.paperId : null,
      submitted: false, result: null
    };
    go('mock');
  }

  var mockTimer = null;

  function stopTimer() { if (mockTimer) { clearInterval(mockTimer); mockTimer = null; } }

  function renderMockRun() {
    var main = document.getElementById('main');
    var m = S.mock;
    var q = BY_KEY[m.keys[m.i]];
    var answered = Object.keys(m.answers).length;

    main.innerHTML =
      '<div class="mock-bar">' +
        '<span class="clock" id="clock">--:--</span>' +
        '<div class="prog" style="flex:1 1 140px"><div class="spread">' +
          '<strong style="font-size:.84rem">' + esc(m.label) + '</strong>' +
          '<span class="dim">' + answered + '/' + m.keys.length + ' answered</span></div>' +
          '<div class="bar"><i style="width:' + pct(answered, m.keys.length) + '%"></i></div></div>' +
        '<button class="btn sm" id="mReview">' +
          (m.review[q.key] ? '★ Marked' : '☆ Mark for review') + '</button>' +
        '<button class="btn sm pri" id="mSubmit">Submit</button>' +
        '<button class="btn sm danger" id="mAbort">Abandon</button>' +
      '</div>' +
      '<div id="mockQ"></div>' +
      '<div class="row mt">' +
        '<button class="btn" id="mPrev"' + (m.i === 0 ? ' disabled' : '') + '>← Previous</button>' +
        '<button class="btn" id="mClear"' + (m.answers[q.key] ? '' : ' disabled') + '>Clear answer</button>' +
        '<button class="btn pri" id="mNext"' +
          (m.i >= m.keys.length - 1 ? ' disabled' : '') + '>Next →</button>' +
      '</div>' +
      '<div class="card mt"><div class="flabel" style="font-size:.7rem;text-transform:uppercase;' +
        'letter-spacing:.06em;color:var(--ink-3);font-weight:650;margin-bottom:.4rem">' +
        'Question palette</div><div class="palette" id="pal"></div>' +
        '<p class="dim" style="margin:.6rem 0 0">Blue = answered, amber = marked for review. ' +
        'No feedback until you submit — that is the point of a mock.</p></div>';

    var host = document.getElementById('mockQ');
    host.appendChild(questionCard(q, {
      mode: 'quiz',
      picked: m.answers[q.key] || null,
      revealed: false,
      num: q.n,
      showPaper: m.mode === 'custom',
      onPick: function (L) {
        m.answers[q.key] = L;
        if (m.i < m.keys.length - 1) m.i++;
        renderMockRun();
      }
    }));

    var pal = document.getElementById('pal');
    m.keys.forEach(function (k, i) {
      var b = document.createElement('button');
      b.textContent = i + 1;
      if (m.answers[k]) b.classList.add('done');
      if (m.review[k]) b.classList.add('review');
      if (i === m.i) b.classList.add('cur');
      b.addEventListener('click', function () { m.i = i; renderMockRun(); });
      pal.appendChild(b);
    });

    document.getElementById('mPrev').addEventListener('click', function () { m.i--; renderMockRun(); });
    document.getElementById('mNext').addEventListener('click', function () { m.i++; renderMockRun(); });
    document.getElementById('mClear').addEventListener('click', function () {
      delete m.answers[q.key]; renderMockRun();
    });
    document.getElementById('mReview').addEventListener('click', function () {
      if (m.review[q.key]) delete m.review[q.key]; else m.review[q.key] = true;
      renderMockRun();
    });
    document.getElementById('mSubmit').addEventListener('click', function () {
      var un = m.keys.length - Object.keys(m.answers).length;
      if (un) {
        openModal('<h2>Submit with ' + un + ' unanswered?</h2>' +
          '<p class="dim">Unanswered questions score zero. With negative marking that is ' +
          'often the right call — a wrong guess costs you.</p>' +
          '<div class="row mt"><button class="btn pri" id="okSub">Submit now</button>' +
          '<button class="btn" id="noSub">Keep working</button></div>',
          function (body) {
            body.querySelector('#okSub').addEventListener('click', function () {
              closeModal(); submitMock();
            });
            body.querySelector('#noSub').addEventListener('click', closeModal);
          });
      } else submitMock();
    });
    document.getElementById('mAbort').addEventListener('click', function () {
      openModal('<h2>Abandon this test?</h2><p class="dim">Nothing is recorded — your ' +
        'attempt history stays as it was.</p><div class="row mt">' +
        '<button class="btn danger" id="okAb">Abandon</button>' +
        '<button class="btn" id="noAb">Keep working</button></div>',
        function (body) {
          body.querySelector('#okAb').addEventListener('click', function () {
            closeModal(); stopTimer(); S.mock = null; go('mock');
          });
          body.querySelector('#noAb').addEventListener('click', closeModal);
        });
    });

    stopTimer();
    tickClock();
    mockTimer = setInterval(tickClock, 1000);
  }

  function tickClock() {
    var m = S.mock;
    var c = document.getElementById('clock');
    if (!m || m.submitted || !c) { stopTimer(); return; }
    var left = m.endsAt - Date.now();
    c.textContent = fmtClock(left);
    c.className = 'clock' + (left < 60000 ? ' crit' : left < 300000 ? ' warn' : '');
    if (left <= 0) {
      stopTimer();
      toast('Time up — submitting');
      submitMock();
    }
  }

  function submitMock() {
    stopTimer();
    var m = S.mock;
    var correct = 0, wrong = 0, score = 0;

    m.keys.forEach(function (k) {
      var choice = m.answers[k];
      if (!choice) return;
      var q = BY_KEY[k];
      var mq = markPerQ(q._paper);
      var ok = record(k, choice);   // feeds the "previously wrong" filter
      if (ok) { correct++; score += mq; }
      else { wrong++; score -= mq * (q._paper.negativeMark || 0); }
    });

    var res = {
      ts: Date.now(), label: m.label, mode: m.mode, paperId: m.paperId,
      total: m.keys.length, answered: Object.keys(m.answers).length,
      correct: correct, wrong: wrong,
      score: score, maxScore: m.maxScore,
      durationMs: Date.now() - m.startedAt,
      keys: m.keys.slice(), answers: Object.assign({}, m.answers)
    };
    DB.tests.unshift(res);
    if (DB.tests.length > 60) DB.tests.length = 60;
    save();

    m.submitted = true;
    m.result = res;
    go('mock');
    window.scrollTo(0, 0);
  }

  function renderMockResult() { renderResultFor(S.mock.result, true); }
  function reviewHistoric(res) { renderResultFor(res, false); }

  function renderResultFor(r, live) {
    var main = document.getElementById('main');
    var skipped = r.total - r.answered;
    var accuracy = pct(r.correct, r.answered || 1);

    var html = '<div class="page-head"><h1>' + esc(r.label) + '</h1>' +
      '<p>' + esc(fmtDate(r.ts)) + ' · finished in ' + esc(fmtClock(r.durationMs)) + '</p></div>';

    html += '<div class="grid g4">' +
      stat('Score', r.score.toFixed(2), 'out of ' + r.maxScore,
           r.score >= r.maxScore * 0.5 ? 'good' : r.score < 0 ? 'bad' : 'warn') +
      stat('Correct', r.correct, accuracy + '% of attempted', 'good') +
      stat('Wrong', r.wrong, r.wrong ? 'cost ' + (r.maxScore ? '' : '') +
           (r.wrong * (marksLost(r) / (r.wrong || 1))).toFixed(2) + ' marks' : '', r.wrong ? 'bad' : '') +
      stat('Left blank', skipped, 'no penalty') +
      '</div>';

    html += '<div class="card mt"><div class="palette" id="rpal"></div>' +
      '<p class="dim" style="margin:.6rem 0 0">Green = right, red = wrong, plain = ' +
      'left blank. Click any number to jump to it below.</p></div>';

    html += '<div class="row mt">' +
      (live ? '<button class="btn pri" id="rDone">Done</button>' : '') +
      '<button class="btn" id="rWrong"' + (r.wrong ? '' : ' disabled') +
        '>Drill the ' + r.wrong + ' you got wrong</button>' +
      '<button class="btn" id="rBack">Back to Mock Test</button>' +
      '</div>';

    html += '<h2 class="mt">Every question, with reasoning</h2><div id="rlist"></div>';
    main.innerHTML = html;

    var pal = document.getElementById('rpal');
    r.keys.forEach(function (k, i) {
      var b = document.createElement('button');
      b.textContent = i + 1;
      var ch = r.answers[k];
      if (ch) b.classList.add(ch === BY_KEY[k].answer ? 'right' : 'wrong');
      b.addEventListener('click', function () {
        var node = document.querySelector('#rlist [data-key="' + k + '"]');
        if (node) node.scrollIntoView({ behavior: 'smooth', block: 'center' });
      });
      pal.appendChild(b);
    });

    var list = document.getElementById('rlist');
    r.keys.forEach(function (k, i) {
      list.appendChild(questionCard(BY_KEY[k], {
        mode: 'result', picked: r.answers[k] || null, num: i + 1,
        showPaper: r.mode === 'custom'
      }));
    });

    var rd = document.getElementById('rDone');
    if (rd) rd.addEventListener('click', function () { S.mock = null; go('mock'); });
    document.getElementById('rBack').addEventListener('click', function () {
      S.mock = null; go('mock');
    });
    var rw = document.getElementById('rWrong');
    if (rw) rw.addEventListener('click', function () {
      var keys = r.keys.filter(function (k) {
        return r.answers[k] && r.answers[k] !== BY_KEY[k].answer;
      });
      S.mock = null;
      S.drill = { keys: keys, i: 0, picked: {}, right: 0, wrong: 0 };
      go('practice');
      window.scrollTo(0, 0);
    });
  }

  function marksLost(r) {
    var lost = 0;
    r.keys.forEach(function (k) {
      var ch = r.answers[k];
      if (!ch) return;
      var q = BY_KEY[k];
      if (ch !== q.answer) lost += markPerQ(q._paper) * (q._paper.negativeMark || 0);
    });
    return lost;
  }

  /* -------------------------------------------------------------- review */

  function viewReview(sub) {
    var main = document.getElementById('main');
    sub = sub || S.reviewTab || 'wrong';
    S.reviewTab = sub;

    var wrong = ALL.filter(function (q) { var a = att(q.key); return a && a.lastOk === false; });
    var ever = ALL.filter(function (q) { var a = att(q.key); return a && a.wrong > 0 && a.lastOk; });
    var dis = ALL.filter(function (q) { return q.disagrees; });
    var flg = ALL.filter(function (q) { return !!q.flag; });
    var low = ALL.filter(function (q) { return q.conf === 'low' || q.conf === 'medium'; });

    var tabs = [
      ['wrong', 'Wrong now', wrong.length,
       'Your most recent answer was wrong. This is the list to clear.'],
      ['fixed', 'Fixed since', ever.length,
       'You got these wrong at some point but your latest answer was right. Worth one more pass before the exam.'],
      ['disagree', 'Differs from marked key', dis.length,
       'The option highlighted in the source PDF is not the answer given here. Those highlights are not an official MPSC key and they do contain errors — but read each one and judge for yourself rather than trusting either side blindly.'],
      ['flagged', 'Defective questions', flg.length,
       'Questions with a real problem: ambiguous wording, two defensible options, no correct option, or a figure the source never reproduced properly.'],
      ['unsure', 'Low / medium confidence', low.length,
       'Where the solver was honestly unsure. These are the ones most worth checking against a textbook.']
    ];

    var html = '<div class="page-head"><h1>Review</h1><p>Five different reasons a question ' +
      'deserves a second look — three about your answers, two about the answers in this ' +
      'bank.</p></div><div class="chips" style="margin-bottom:1rem">';
    tabs.forEach(function (t) {
      html += '<button class="chip' + (sub === t[0] ? ' on' : '') + '" data-rt="' + t[0] + '">' +
        esc(t[1]) + '<span class="c">' + t[2] + '</span></button>';
    });
    html += '</div><div id="rvBody"></div>';
    main.innerHTML = html;

    main.querySelectorAll('[data-rt]').forEach(function (b) {
      b.addEventListener('click', function () { viewReview(b.dataset.rt); });
    });

    var pick = { wrong: wrong, fixed: ever, disagree: dis, flagged: flg, unsure: low }[sub] || [];
    var meta = tabs.filter(function (t) { return t[0] === sub; })[0];
    var body = document.getElementById('rvBody');

    body.appendChild(el('<div class="card" style="margin-bottom:1rem">' +
      '<p style="margin:0" class="muted">' + esc(meta[3]) + '</p>' +
      (pick.length ? '<div class="row mt"><button class="btn pri" id="rvDrill">Drill these ' +
        pick.length + '</button></div>' : '') + '</div>'));

    if (!pick.length) {
      body.appendChild(el('<div class="empty"><div class="big">✓</div>' +
        '<p>Nothing here.</p></div>'));
      return;
    }
    var d = document.getElementById('rvDrill');
    if (d) d.addEventListener('click', function () {
      S.drill = { keys: pick.map(function (q) { return q.key; }), i: 0, picked: {}, right: 0, wrong: 0 };
      go('practice');
      window.scrollTo(0, 0);
    });

    pick.forEach(function (q, i) {
      var a = att(q.key);
      body.appendChild(questionCard(q, {
        mode: 'result', picked: a ? a.last : null, num: i + 1, showPaper: true
      }));
    });
  }

  /* ------------------------------------------------------------ progress */

  function viewProgress() {
    var main = document.getElementById('main');
    var rows = [];
    (META.topics || []).forEach(function (t) {
      var qs = ALL.filter(function (q) { return q.topic === t.slug; });
      var done = 0, ok = 0;
      qs.forEach(function (q) { var a = att(q.key); if (a) { done++; if (a.lastOk) ok++; } });
      rows.push({ label: t.label, group: t.group, total: qs.length, done: done, ok: ok });
    });

    var groupLabel = {};
    (META.groups || []).forEach(function (g) { groupLabel[g.slug] = g.label; });

    var html = '<div class="page-head"><h1>Progress</h1><p>Accuracy is measured on your ' +
      '<em>latest</em> answer to each question, so fixing a mistake actually moves the number.' +
      '</p></div>';

    var attempted = 0, ok = 0;
    ALL.forEach(function (q) { var a = att(q.key); if (a) { attempted++; if (a.lastOk) ok++; } });
    html += '<div class="grid g4">' +
      stat('Bank covered', pct(attempted, ALL.length) + '%', attempted + ' of ' + ALL.length) +
      stat('Accuracy', (attempted ? pct(ok, attempted) : 0) + '%', 'on latest answers',
           attempted && pct(ok, attempted) >= 60 ? 'good' : 'warn') +
      stat('Tests taken', DB.tests.length, '') +
      stat('Total attempts', Object.keys(DB.attempts).reduce(function (s, k) {
        return s + DB.attempts[k].n; }, 0), 'including repeats') +
      '</div>';

    html += '<div class="card mt"><h2>By topic</h2><div class="scroll-x"><table>' +
      '<thead><tr><th>Topic</th><th class="num">Qs</th><th class="num">Done</th>' +
      '<th class="num">Accuracy</th><th style="width:120px">Coverage</th></tr></thead><tbody>';
    var lastG = null;
    rows.forEach(function (r) {
      if (r.group !== lastG) {
        lastG = r.group;
        html += '<tr><td colspan="5" style="background:var(--panel-2);font-weight:650;' +
          'font-size:.8rem">' + esc(groupLabel[r.group] || r.group) + '</td></tr>';
      }
      var acc = r.done ? pct(r.ok, r.done) : null;
      html += '<tr><td>' + esc(r.label) + '</td><td class="num">' + r.total + '</td>' +
        '<td class="num">' + r.done + '</td>' +
        '<td class="num">' + (acc == null ? '<span class="dim">—</span>' :
          '<span class="pill ' + (acc >= 70 ? 'ok' : acc >= 40 ? 'wn' : 'no') + '">' +
          acc + '%</span>') + '</td>' +
        '<td><div class="bar"><i style="width:' + pct(r.done, r.total) + '%"></i></div></td></tr>';
    });
    html += '</tbody></table></div></div>';
    main.innerHTML = html;
  }

  /* --------------------------------------------------------------- modal */

  function openModal(html, wire) {
    var m = document.getElementById('modal');
    var body = document.getElementById('modalBody');
    body.innerHTML = html;
    m.hidden = false;
    if (wire) wire(body);
  }
  function closeModal() { document.getElementById('modal').hidden = true; }

  function dataModal() {
    var n = Object.keys(DB.attempts).length;
    openModal(
      '<h2>Your progress</h2>' +
      '<p class="dim">Attempt history lives in this browser’s local storage only — ' +
      'nothing is uploaded anywhere. Clearing site data wipes it, so export before you ' +
      'switch browsers.</p>' +
      '<p><strong>' + n + '</strong> questions attempted · <strong>' + DB.tests.length +
      '</strong> tests recorded</p>' +
      '<div class="row mt"><button class="btn" id="dExp">Export JSON</button>' +
      '<button class="btn" id="dImp">Import JSON</button>' +
      '<button class="btn danger" id="dDel">Reset everything</button></div>' +
      '<input type="file" id="dFile" accept="application/json" hidden>',
      function (body) {
        body.querySelector('#dExp').addEventListener('click', function () {
          var blob = new Blob([JSON.stringify(DB, null, 1)], { type: 'application/json' });
          var a = document.createElement('a');
          a.href = URL.createObjectURL(blob);
          a.download = 'mpsc-practice-hub-2-progress.json';
          a.click();
          URL.revokeObjectURL(a.href);
        });
        var file = body.querySelector('#dFile');
        body.querySelector('#dImp').addEventListener('click', function () { file.click(); });
        file.addEventListener('change', function () {
          var f = file.files[0];
          if (!f) return;
          var fr = new FileReader();
          fr.onload = function () {
            try {
              var d = JSON.parse(fr.result);
              if (!d || typeof d.attempts !== 'object') throw new Error('not a progress file');
              DB.attempts = d.attempts || {};
              DB.tests = Array.isArray(d.tests) ? d.tests : [];
              DB.prefs = Object.assign(DB.prefs, d.prefs || {});
              save();
              closeModal();
              toast('Progress restored');
              render();
            } catch (e) {
              toast('That file is not a Practice Hub progress export');
            }
          };
          fr.readAsText(f);
        });
        body.querySelector('#dDel').addEventListener('click', function () {
          openModal('<h2>Reset all progress?</h2><p class="dim">Every attempt and every test ' +
            'result is deleted. This cannot be undone — export first if you are unsure.</p>' +
            '<div class="row mt"><button class="btn danger" id="rlyDel">Yes, delete it all</button>' +
            '<button class="btn" id="noDel">Cancel</button></div>',
            function (b2) {
              b2.querySelector('#rlyDel').addEventListener('click', function () {
                DB.attempts = {}; DB.tests = []; save();
                closeModal(); toast('Progress reset'); render();
              });
              b2.querySelector('#noDel').addEventListener('click', closeModal);
            });
        });
      }
    );
  }

  /* --------------------------------------------------------------- router */

  function go(view, arg) {
    if (S.view === 'mock' && view !== 'mock') stopTimer();
    S.view = view;
    if (view === 'review' && arg) S.reviewTab = arg;
    document.querySelectorAll('#tabs button').forEach(function (b) {
      b.classList.toggle('on', b.dataset.view === view);
    });
    render();
    if (view !== 'mock') window.scrollTo(0, 0);
  }

  function render() {
    var v = S.view;
    if (v === 'dash') viewDash();
    else if (v === 'papers') viewPapers();
    else if (v === 'current-affairs') viewCurrentAffairs();
    else if (v === 'practice') viewPractice();
    else if (v === 'mock') viewMock();
    else if (v === 'review') viewReview(S.reviewTab);
    else if (v === 'progress') viewProgress();
  }

  /* ----------------------------------------------------------------- boot */

  function applyTheme(t) {
    document.documentElement.setAttribute('data-theme', t);
    DB.prefs.theme = t;
    save();
  }

  async function boot() {
    try {
      await loadCurrentAffairs();
    } catch (e) {
      console.warn('[ph2] current affairs could not be loaded; past papers remain available', e);
    }
    if (!PAPERS.length) {
      document.getElementById('main').innerHTML =
        '<div class="card"><h1>No question data loaded</h1>' +
        '<p>The app booted but <code>data/papers.js</code> is empty or missing. Build it:</p>' +
        '<pre><code>python3 tools/practice-hub-build/build.py</code></pre></div>';
      return;
    }

    applyTheme(DB.prefs.theme || 'auto');

    var t = META.totals || {};
    document.getElementById('brandSub').textContent =
      t.questions + ' questions · ' + t.papers + ' papers';

    document.querySelectorAll('#tabs button').forEach(function (b) {
      b.addEventListener('click', function () { go(b.dataset.view); });
    });
    document.getElementById('themeBtn').addEventListener('click', function () {
      var order = ['auto', 'light', 'dark'];
      var cur = document.documentElement.getAttribute('data-theme') || 'auto';
      applyTheme(order[(order.indexOf(cur) + 1) % 3]);
      toast('Theme: ' + DB.prefs.theme);
    });
    document.getElementById('dataBtn').addEventListener('click', dataModal);
    document.getElementById('modalX').addEventListener('click', closeModal);
    document.getElementById('modal').addEventListener('click', function (e) {
      if (e.target.id === 'modal') closeModal();
    });

    document.addEventListener('keydown', function (e) {
      if (e.target.matches('input, textarea, select')) return;
      if (e.key === 'Escape') { closeModal(); return; }

      // a/b/c/d to answer, Enter to advance — a mock of 100 questions is
      // unpleasant to click through.
      var live = (S.view === 'practice' && S.drill) || (S.view === 'mock' && S.mock && !S.mock.submitted);
      if (!live) return;

      var L = e.key.toLowerCase();
      if (LETTERS.indexOf(L) >= 0) {
        var btn = document.querySelector('#mockQ .opt[data-letter="' + L + '"], ' +
                                         '#drillQ .opt[data-letter="' + L + '"]');
        if (btn && !btn.disabled) { e.preventDefault(); btn.click(); }
      } else if (e.key === 'Enter') {
        var nx = document.querySelector('#drillNav .btn.pri, #mNext');
        if (nx && !nx.disabled) { e.preventDefault(); nx.click(); }
      } else if (e.key === 'ArrowRight') {
        var n2 = document.getElementById('mNext');
        if (n2 && !n2.disabled) n2.click();
      } else if (e.key === 'ArrowLeft') {
        var p2 = document.getElementById('mPrev');
        if (p2 && !p2.disabled) p2.click();
      }
    });

    window.addEventListener('beforeunload', function (e) {
      if (S.mock && !S.mock.submitted) {
        e.preventDefault();
        e.returnValue = '';
      }
    });

    go('dash');
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else boot();
})();
